import test from 'node:test';
import assert from 'node:assert/strict';
import { countOccurrences } from '../src/count-occurrences.mjs';
test('counts non-overlapping occurrences', () => assert.equal(countOccurrences('abcabcabc', 'abc'), 3));
test('counts overlapping occurrences', () => assert.equal(countOccurrences('aaaa', 'aa'), 3));
test('handles absent matches and an empty haystack', () => { assert.equal(countOccurrences('abc', 'z'), 0); assert.equal(countOccurrences('', 'x'), 0); });
test('matches literally at boundaries, case-sensitively', () => { assert.equal(countOccurrences('a.a.', 'a.'), 2); assert.equal(countOccurrences('AaA', 'A'), 2); assert.equal(countOccurrences('abc', 'abc'), 1); });
test('rejects an empty needle and non-string inputs', () => { assert.throws(() => countOccurrences('abc', ''), RangeError); for (const value of [null, undefined, 3, {}, []]) { assert.throws(() => countOccurrences(value, 'a'), TypeError); assert.throws(() => countOccurrences('a', value), TypeError); } });
